<template><q-card flat bordered class="cart-card" :class="{locked:bloqueada}"><q-card-section class="cart-head row items-center"><div><div class="cart-title">Detalle de la venta</div><div class="cart-sub">{{items.length}} producto(s) agregado(s)</div></div><q-space/><q-btn v-if="items.length" :disable="bloqueada" flat dense color="negative" icon="delete_sweep" label="Vaciar" no-caps @click="$emit('vaciar')"/></q-card-section><q-separator/><q-card-section v-if="items.length" class="cart-body"><div v-for="item in items" :key="item.id" class="cart-item"><div><div class="item-code">{{item.codigo}}</div><div class="item-name">{{item.nombre}}</div><div class="item-meta">Precio unitario: Bs {{item.precio.toFixed(2)}}</div></div><div class="quantity"><q-btn :disable="bloqueada" round flat dense icon="remove" color="green-8" @click="$emit('cantidad',item,-1)"/><q-input :disable="bloqueada" class="quantity-input" :model-value="item.cantidad" outlined dense type="text" @update:model-value="$emit('cantidad-directa',item,$event)" @blur="$emit('cantidad-blur',item)"/><q-btn :disable="bloqueada" round flat dense icon="add" color="green-8" @click="$emit('cantidad',item,1)"/></div><div class="item-total">Bs {{(item.precio*item.cantidad).toFixed(2)}}</div><q-btn :disable="bloqueada" flat round dense icon="close" color="grey-6" @click="$emit('quitar',item)"/></div></q-card-section><div v-else class="cart-empty"><q-icon name="shopping_cart" size="54px" color="green-3"/><div>El carrito está vacío</div></div><q-separator v-if="items.length"/><q-card-section class="totals"><div><span>Subtotal</span><b>Bs {{subtotal.toFixed(2)}}</b></div><div class="grand-total"><span>Total</span><b>Bs {{subtotal.toFixed(2)}}</b></div></q-card-section><q-card-actions class="payment-actions"><q-btn class="hold-btn" flat no-caps icon="pause_circle" label="Poner en espera" :disable="bloqueada||!items.length" @click="$emit('espera')"/><q-btn class="payment-btn" unelevated no-caps color="green-8" icon="payments" label="Registrar pago" :disable="bloqueada||!items.length" @click="$emit('pagar',subtotal)"/><q-btn class="credit-btn" unelevated no-caps color="orange-8" icon="credit_score" label="Venta a crédito" :disable="bloqueada||!items.length" @click="$emit('credito',subtotal)"/></q-card-actions></q-card></template>
<script setup>import{computed}from'vue';const props=defineProps({items:{type:Array,default:()=>[]},bloqueada:Boolean});defineEmits(['vaciar','cantidad','cantidad-directa','cantidad-blur','quitar','pagar','credito','espera']);const subtotal=computed(()=>props.items.reduce((s,i)=>s+i.precio*i.cantidad,0))</script>
<style scoped>.cart-card{border-radius:18px;border-color:#dfeae1;height:100%}.cart-card.locked{opacity:.65}.cart-head{padding:16px 18px}.cart-title{color:#1b5e20;font-weight:900;font-size:17px}.cart-sub,.item-meta{color:#789080;font-size:11px;margin-top:3px}.cart-body{padding:4px 18px}.cart-item{display:grid;grid-template-columns:1fr auto auto auto;align-items:center;gap:10px;padding:14px 0;border-bottom:1px solid #edf2ee}.item-code{color:#789080;font-size:10px}.item-name{color:#263238;font-weight:800}.quantity{display:flex;align-items:center;gap:4px}.quantity-input{width:82px}.item-total{color:#2e7d32;font-weight:900}.cart-empty{min-height:230px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#60756a}.totals{padding:14px 18px}.totals>div{display:flex;justify-content:space-between;padding:5px 0;color:#789080}.grand-total{border-top:1px solid #dfeae1;margin-top:7px;padding-top:13px!important;color:#1b5e20!important;font-size:20px;font-weight:900}.payment-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:0 18px 18px}.hold-btn{grid-column:1/-1}.payment-btn,.credit-btn,.hold-btn{width:100%;border-radius:10px;font-weight:800}@media(max-width:600px){.cart-item{grid-template-columns:1fr auto}.item-total{grid-column:1}}</style>
